/** The one focus ring (D5): 2 dp in colors.focus, drawn 2 dp outside the element, never animated. */
@Composable
fun Modifier.sbFocusRing(interactionSource: InteractionSource, cornerRadius: Dp): Modifier {
    val focused by interactionSource.collectIsFocusedAsState()
    val color = SebaroTheme.colors.focus
    val focus = SebaroTheme.tokens.focus
    return drawWithContent {
        drawContent()
        if (focused) {
            val w = focus.width.toPx()
            val o = focus.offset.toPx() + w / 2f
            drawRoundRect(
                color = color,
                topLeft = Offset(-o, -o),
                size = Size(size.width + 2 * o, size.height + 2 * o),
                cornerRadius = CornerRadius(cornerRadius.toPx() + o),
                style = Stroke(width = w),
            )
        }
    }
}

/** The same ring around any [shape] (the bevelled destructive action): the shape at the ring's size, 2 dp outside. */
@Composable
fun Modifier.sbFocusRing(interactionSource: InteractionSource, shape: Shape): Modifier {
    val focused by interactionSource.collectIsFocusedAsState()
    val color = SebaroTheme.colors.focus
    val focus = SebaroTheme.tokens.focus
    return drawWithContent {
        drawContent()
        if (focused) {
            val w = focus.width.toPx()
            val o = focus.offset.toPx() + w / 2f
            val outline = shape.createOutline(Size(size.width + 2 * o, size.height + 2 * o), layoutDirection, this)
            translate(-o, -o) { drawOutline(outline, color, style = Stroke(width = w)) }
        }
    }
}

/** The same 2 dp ring drawn inside the element: full-width rows and menu rows, whose outside is the screen edge. */
@Composable
fun Modifier.sbFocusRingInset(interactionSource: InteractionSource): Modifier {
    val focused by interactionSource.collectIsFocusedAsState()
    val color = SebaroTheme.colors.focus
    val focus = SebaroTheme.tokens.focus
    return drawWithContent {
        drawContent()
        if (focused) {
            val w = focus.width.toPx()
            drawRect(color, topLeft = Offset(w / 2f, w / 2f), size = Size(size.width - w, size.height - w), style = Stroke(width = w))
        }
    }
}

/**
 * Keeps a whole part in view while the focus is on a control inside it (CHECKS.md §84; provisional, agent): a sentence
 * and its action or its SbErrorDetails in a scrolling list, where the scroll to the focus alone shows only the control.
 * SbCallout has it. A part taller than its list shows what fits, with the focused control in it.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
fun Modifier.sbShowWholeOnFocus(): Modifier {
    val requester = remember { BringIntoViewRequester() }
    val scope = rememberCoroutineScope()
    val whole = remember { mutableStateOf(IntSize.Zero) }
    val ring = with(LocalDensity.current) { (SebaroTheme.tokens.focus.offset + SebaroTheme.tokens.focus.width).toPx() }
    return onSizeChanged { whole.value = it }.bringIntoViewRequester(requester).onFocusEvent { state ->
        // with the ring's room around it: a control at the part's edge keeps its ring in a part taller than the list
        val size = whole.value
        if (state.hasFocus) scope.launch { requester.bringIntoView(Rect(-ring, -ring, size.width + ring, size.height + ring)) }
    }
}

/**
 * The arrow and page keys for a scrolling area with nothing to focus in it, as a long text (CHECKS.md §84; provisional,
 * agent). Put it on the list or the verticalScroll's parent with its [state]. The area is one focus stop while it can
 * scroll, with the inset ring; Down and Up move it by 48 dp at once, or nine tenths of its height when that is less, Page
 * Down and Page Up by nine tenths of its height, and at its end the key moves the focus on, first to a control inside it,
 * so it is no trap. TalkBack gets no new node. Not for a list of targets: there the arrow keys already move through them.
 */
@Composable
fun Modifier.sbScrollKeys(state: ScrollableState): Modifier = sbScrollKeys(state) { 0 }

/** [sbScrollKeys] for the system's own areas (CHECKS.md §87): [covered] px of the area's end lie under a pinned action. */
@Composable
internal fun Modifier.sbScrollKeys(state: ScrollableState, covered: () -> Int): Modifier {
    val t = SebaroTheme.tokens
    val scope = rememberCoroutineScope()
    val focused = remember { mutableStateOf(false) }
    val ring = SebaroTheme.colors.focus
    val height = remember { mutableIntStateOf(0) }
    val line = with(LocalDensity.current) { t.size.targetTouch.toPx() }
    val focusManager = LocalFocusManager.current
    val input = LocalInputModeManager.current
    return onSizeChanged { height.intValue = it.height }
        // from the focus itself: an interaction sent before its watcher runs is lost, and a first focus would show no ring (CHECKS.md §95)
        .drawWithContent {
            drawContent()
            if (focused.value) {
                val w = t.focus.width.toPx()
                drawRect(ring, topLeft = Offset(w / 2f, w / 2f), size = Size(size.width - w, size.height - w), style = Stroke(width = w))
            }
        }
        // a stop for keys only: back with a finger its ring goes too (CHECKS.md §88)
        .focusProperties { canFocus = input.inputMode == InputMode.Keyboard && (state.canScrollForward || state.canScrollBackward) }
        .onFocusChanged { focused.value = it.isFocused }
        .onKeyEvent { e ->
            if (!focused.value) return@onKeyEvent false
            // a stop has nothing to press: Enter would go on into the area, past its words, onto its first key (CHECKS.md §96)
            if (e.key == Key.Enter || e.key == Key.NumPadEnter || e.key == Key.DirectionCenter) return@onKeyEvent true
            if (e.type != KeyEventType.KeyDown) return@onKeyEvent false
            // an action that covers the whole area leaves no room to measure by: the step of an uncovered one
            val page = (height.intValue - covered()).let { if (it > 0) it else height.intValue } * 0.9f
            val by = when (e.key) {
                Key.DirectionDown -> minOf(line, page)
                Key.DirectionUp -> -minOf(line, page)
                Key.PageDown -> page
                Key.PageUp -> -page
                else -> return@onKeyEvent false
            }
            if (if (by > 0f) !state.canScrollForward else !state.canScrollBackward) {
                // a control inside comes after the words (a callout's action, a failed action's details)
                return@onKeyEvent by > 0f && focusManager.moveFocus(FocusDirection.Next)
            }
            scope.launch { state.scrollBy(by) }
            true
        }
        .focusTarget()
}

/**
 * The sign that an area holds more than it shows (D134; CHECKS.md §87, §90): a 3 dp mark in borderStrong at the area's
 * end, as long as the part it shows, and the words running out into the ground over the last 36 dp, while [state] can
 * scroll, so a cut sentence cannot look complete. [outside] moves the mark past the area's edge, into a gutter. The fade
 * ends at [fadeEnd], and weakens as the [unseen] px left get fewer than its height, so it is gone at the end. It starts
 * no higher than [fadeFrom], so an action in the area is not dimmed: it would look locked (CHECKS.md §93). While the
 * focus is in the area it stays away: it would dim the control in focus or the area's own ring. [fade] = false: the mark
 * alone, for an area of controls, where a dimmed key looks locked as well. Put it before verticalScroll, whose clip
 * would cut it. It draws only.
 */
@Composable
internal fun Modifier.sbScrollMark(
    state: ScrollState,
    color: Color,
    outside: Dp = 0.dp,
    fadeEnd: DrawScope.() -> Float = { size.height },
    unseen: () -> Int = { state.maxValue - state.value },
    fadeFrom: DrawScope.() -> Float = { 0f },
    fade: Boolean = true,
): Modifier {
    val ground = SebaroTheme.colors.bg
    var focused by remember { mutableStateOf(false) }
    return onFocusChanged { focused = it.hasFocus }.drawWithContent {
        drawContent()
        val whole = state.viewportSize + state.maxValue
        if (state.maxValue > 0 && state.maxValue < Int.MAX_VALUE && whole > 0) {
            val tall = 36.dp.toPx()
            val rest = unseen()
            val end = fadeEnd()
            val from = maxOf(end - tall, fadeFrom())
            if (fade && !focused && rest > 0 && from < end) {
                val brush = Brush.verticalGradient(
                    0f to ground.copy(alpha = 0f),
                    1f to ground.copy(alpha = minOf(1f, rest / tall)),
                    startY = from,
                    endY = end,
                )
                drawRect(brush, Offset(0f, from), Size(size.width, end - from))
            }
            val w = 3.dp.toPx()
            // never so short that it shows no pixel (CHECKS.md §96)
            val h = minOf(size.height, maxOf(size.height * state.viewportSize / whole, 12.dp.toPx()))
            val y = (size.height - h) * state.value / state.maxValue
            val x = if (layoutDirection == LayoutDirection.Rtl) -outside.toPx() else size.width + outside.toPx() - w
            drawRect(color, Offset(x, y), Size(w, h))
        }
    }
}
